-- পৌল, প্রেরিত খ্রীষ্টের যীশুর দ্বারা ইচ্ছার ঈশ্বরের, এবং তীমথিয়, সেই– ভাই; সেই– মণ্ডলীকে সেই– ঈশ্বরের সেই– যে–আছে মধ্যে– করিন্থে, সহ– সেই– পবিত্র সকলদের, সেই– যারা–আছে মধ্যে– সমস্ত সেই– আখায়ায়।

BEGIN;
-- 4700100101: Παῦλος, (G3972) → "পৌল," [opus-4.5-chirho]
WITH np AS (
  INSERT INTO phrase (language_id, created_at)
  SELECT (SELECT id FROM language WHERE code = 'ben'), NOW()
  WHERE NOT EXISTS (
    SELECT 1 FROM phrase p JOIN phrase_word pw ON pw.phrase_id = p.id
    WHERE pw.word_id = '4700100101' AND p.language_id = (SELECT id FROM language WHERE code = 'ben') AND p.deleted_at IS NULL
  )
  RETURNING id
)
INSERT INTO phrase_word (phrase_id, word_id) SELECT id, '4700100101' FROM np ON CONFLICT DO NOTHING;
INSERT INTO gloss (phrase_id, gloss, state, updated_at, source)
SELECT p.id, 'পৌল,', 'UNAPPROVED', NOW(), 'IMPORT'
FROM phrase p JOIN phrase_word pw ON pw.phrase_id = p.id
WHERE pw.word_id = '4700100101' AND p.language_id = (SELECT id FROM language WHERE code = 'ben') AND p.deleted_at IS NULL
ON CONFLICT (phrase_id) DO UPDATE SET gloss = EXCLUDED.gloss, updated_at = EXCLUDED.updated_at, source = EXCLUDED.source;
